+        String data;
+        boolean notFile;
+
+        private Entry(String name, String data, boolean notFile) {
+            this.name = name;
+            this.data = data;
+            this.notFile = notFile;
+        }
+
+        @Override
+        public String toString() {
+            return name;
+        }
+    }
